// Code generated by strictgen. DO NOT EDIT.

//! Built in types and decoding functions the generated modules share.

use std::borrow::Cow;
use std::collections::{BTreeMap, HashMap};
use std::fmt;

use serde::Serialize;

/// serde_json's recursion limit: a value nested in 128 or more arrays and objects fails, so
/// Rust, Go and TypeScript accept the same documents and decoding stays bounded.
const MAX_DEPTH: usize = 128;

/// The number of code points of a string an error shows, before "...".
const FOUND_MAX: usize = 64;

/// A value that doesn't fit its generated type, or input that isn't JSON. Go and TypeScript
/// report the same path, code, expected and found for the same input, and the same message.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DecodeError {
    /// A JSON Pointer to the value that failed, like /items/0/price, empty for the whole input.
    pub path: String,
    /// What failed, one of the code constants, like DecodeError::MISSING_KEY.
    pub code: &'static str,
    /// What the type takes there, like "a string", when the code has one.
    pub expected: Option<String>,
    /// What the input has there, like 12.5 or "x", when the code has one.
    pub found: Option<String>,
}

impl DecodeError {
    /// The code for a key the type doesn't name, at the key's path.
    pub const UNKNOWN_KEY: &'static str = "unknown_key";
    /// The code for a required key that is absent, at the key's path.
    pub const MISSING_KEY: &'static str = "missing_key";
    /// The code for null where the type doesn't take it, like for an optional key.
    pub const NULL_NOT_ALLOWED: &'static str = "null_not_allowed";
    /// The code for a value of another JSON type, or a fraction for an integer.
    pub const WRONG_TYPE: &'static str = "wrong_type";
    /// The code for a tag that no branch of a tagged union has, at the tag's path.
    pub const BAD_TAG: &'static str = "bad_tag";
    /// The code for a string the enum doesn't list.
    pub const NOT_IN_ENUM: &'static str = "not_in_enum";
    /// The code for a value other than the const.
    pub const NOT_CONST: &'static str = "not_const";
    /// The code for a string, array or map with fewer code points, items or keys than its minimum.
    pub const TOO_SHORT: &'static str = "too_short";
    /// The code for a string, array or map with more code points, items or keys than its maximum.
    pub const TOO_LONG: &'static str = "too_long";
    /// The code for a number below its minimum.
    pub const TOO_SMALL: &'static str = "too_small";
    /// The code for a number above its maximum.
    pub const TOO_LARGE: &'static str = "too_large";
    /// The code for an integer that isn't a multiple of its multipleOf.
    pub const NOT_MULTIPLE_OF: &'static str = "not_multiple_of";
    /// The code for a string that doesn't match its pattern.
    pub const PATTERN_MISMATCH: &'static str = "pattern_mismatch";
    /// The code for a string that isn't in its format, like date-time.
    pub const BAD_FORMAT: &'static str = "bad_format";
    /// The code for an array whose items must be unique, with a repeat.
    pub const NOT_UNIQUE: &'static str = "not_unique";
    /// The code for an integer the language can't hold exactly.
    pub const OUT_OF_RANGE_INTEGER: &'static str = "out_of_range_integer";
    /// The code for text that isn't JSON: a syntax error, invalid UTF-8, a lone surrogate, data after the value or a number out of range.
    pub const INVALID_JSON: &'static str = "invalid_json";
    /// The code for an object that gives the same key twice, at the key's path.
    pub const DUPLICATE_KEY: &'static str = "duplicate_key";
    /// The code for a value inside 128 or more arrays and objects.
    pub const TOO_DEEP: &'static str = "too_deep";

    /// The one-line form, made for logs and for asking an LLM to retry, like
    /// /items/0 wrong_type, expected a string, found 1.
    #[must_use]
    pub fn compact(&self) -> String {
        describe(
            &self.path,
            self.code,
            " ",
            self.expected.as_deref(),
            self.found.as_deref(),
        )
    }

    /// An error at the current value.
    fn new(code: &'static str, expected: Option<String>, found: Option<String>) -> Self {
        Self {
            path: String::new(),
            code,
            expected,
            found,
        }
    }

    /// Moves the error one level down, under an object key or array index.
    fn at(mut self, segment: &str) -> Self {
        self.path.insert_str(0, &pointer(segment));
        self
    }
}

impl fmt::Display for DecodeError {
    /// Writes the message, like /items/0: wrong type, expected a string, found 1.
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let head = title(self.code);
        f.write_str(&describe(
            &self.path,
            head,
            ": ",
            self.expected.as_deref(),
            self.found.as_deref(),
        ))
    }
}

impl std::error::Error for DecodeError {}

/// The words for a code in a message.
fn title(code: &str) -> &'static str {
    match code {
        "unknown_key" => "unknown key",
        "missing_key" => "missing key",
        "null_not_allowed" => "null not allowed",
        "wrong_type" => "wrong type",
        "bad_tag" => "bad tag",
        "not_in_enum" => "not in enum",
        "not_const" => "not const",
        "too_short" => "too short",
        "too_long" => "too long",
        "too_small" => "too small",
        "too_large" => "too large",
        "not_multiple_of" => "not a multiple",
        "pattern_mismatch" => "pattern mismatch",
        "bad_format" => "bad format",
        "not_unique" => "not unique",
        "out_of_range_integer" => "out of range integer",
        "invalid_json" => "invalid JSON",
        "duplicate_key" => "duplicate key",
        "too_deep" => "too deep",
        _ => "",
    }
}

/// Builds a message: the path, then head, then expected and found when they are set.
fn describe(
    path: &str,
    head: &str,
    gap: &str,
    expected: Option<&str>,
    found: Option<&str>,
) -> String {
    let mut text = String::new();
    if !path.is_empty() {
        text.push_str(path);
        text.push_str(gap);
    }
    text.push_str(head);
    if let Some(expected) = expected.filter(|e| !e.is_empty()) {
        text.push_str(", expected ");
        text.push_str(expected);
    }
    if let Some(found) = found.filter(|f| !f.is_empty()) {
        text.push_str(", found ");
        text.push_str(found);
    }
    text
}

/// A JSON Pointer segment, with its slash.
fn pointer(segment: &str) -> String {
    format!("/{}", segment.replace('~', "~0").replace('/', "~1"))
}

/// Shows a string as errors do in every language: in double quotes, with " and \ escaped by a
/// backslash and control characters (U+0000 to U+001F, U+007F to U+009F), U+2028 and U+2029 as
/// \u and four hex digits. A string of more than FOUND_MAX code points shows its first
/// FOUND_MAX, then ... after the quote.
fn quote(text: &str) -> String {
    let mut out = String::with_capacity(text.len() + 2);
    out.push('"');
    for (count, c) in text.chars().enumerate() {
        if count == FOUND_MAX {
            out.push_str("\"...");
            return out;
        }
        match c {
            '"' | '\\' => {
                out.push('\\');
                out.push(c);
            }
            '\u{0}'..='\u{1f}' | '\u{7f}'..='\u{9f}' | '\u{2028}' | '\u{2029}' => {
                let code = u32::from(c);
                out.push_str("\\u");
                for shift in [12, 8, 4, 0] {
                    out.push(char::from_digit((code >> shift) & 0xf, 16).unwrap_or('0'));
                }
            }
            _ => out.push(c),
        }
    }
    out.push('"');
    out
}

/// One parsed JSON value. Input is parsed once, then decoders walk the nodes, so decoding is
/// linear in the input size.
#[doc(hidden)]
pub struct Node<'a> {
    /// The value as spelled in the input.
    raw: &'a str,
    /// The byte offset of the value in the input.
    at: usize,
    kind: Kind<'a>,
}

enum Kind<'a> {
    Null,
    True,
    False,
    Number,
    String(Cow<'a, str>),
    Array(Vec<Node<'a>>),
    Object(Members<'a>),
}

/// The members of an object in input order, each key once.
#[derive(Default)]
struct Members<'a> {
    entries: Vec<(Cow<'a, str>, Node<'a>)>,
    /// The position of each key, once the object has more than a few.
    index: Option<HashMap<Cow<'a, str>, usize>>,
}

/// Objects with more keys than this look keys up through an index.
const INDEX_FROM: usize = 8;

impl<'a> Members<'a> {
    /// The position of key, if the object has it.
    fn find(&self, key: &str) -> Option<usize> {
        match &self.index {
            Some(index) => index.get(key).copied(),
            None => self.entries.iter().position(|(name, _)| name == key),
        }
    }

    /// Adds a member whose key the object doesn't have yet.
    fn push(&mut self, key: Cow<'a, str>, node: Node<'a>) {
        let at = self.entries.len();
        if let Some(index) = &mut self.index {
            index.insert(key.clone(), at);
        } else if at == INDEX_FROM {
            let mut index: HashMap<Cow<'a, str>, usize> = self
                .entries
                .iter()
                .enumerate()
                .map(|(i, (name, _))| (name.clone(), i))
                .collect();
            index.insert(key.clone(), at);
            self.index = Some(index);
        }
        self.entries.push((key, node));
    }
}

impl<'a> Node<'a> {
    /// A string node for an object key, so a map key decodes like a JSON string.
    fn key(name: &'a str) -> Self {
        Node {
            raw: "",
            at: 0,
            kind: Kind::String(Cow::Borrowed(name)),
        }
    }
}

/// Shows a value as errors do: null, true and false, a number as spelled, a string quoted,
/// "an array" and "an object".
fn found(node: &Node<'_>) -> String {
    match &node.kind {
        Kind::Object(_) => "an object".to_owned(),
        Kind::Array(_) => "an array".to_owned(),
        Kind::String(text) => quote(text),
        Kind::Null => "null".to_owned(),
        Kind::True => "true".to_owned(),
        Kind::False => "false".to_owned(),
        Kind::Number => node.raw.to_owned(),
    }
}

/// The error for a value that is not what expected names: null_not_allowed for null, else
/// wrong_type.
pub(super) fn mismatch(expected: &str, node: &Node<'_>) -> DecodeError {
    if matches!(node.kind, Kind::Null) {
        return DecodeError::new(
            DecodeError::NULL_NOT_ALLOWED,
            Some(expected.to_owned()),
            None,
        );
    }
    DecodeError::new(
        DecodeError::WRONG_TYPE,
        Some(expected.to_owned()),
        Some(found(node)),
    )
}

/// An invalid_json error, what was found at a byte offset.
fn invalid(offset: usize, what: &str) -> DecodeError {
    DecodeError::new(
        DecodeError::INVALID_JSON,
        None,
        Some(format!("{what} at offset {offset}")),
    )
}

/// Reads JSON like serde_json: strict grammar, valid UTF-8, no lone surrogates, finite numbers
/// and at most MAX_DEPTH - 1 nested arrays and objects. Every failure carries its error code and
/// the JSON Pointer of the value being read, and found gives the byte offset.
struct Parser<'a> {
    text: &'a str,
    pos: usize,
}

/// Parses a whole JSON document.
fn parse(data: &[u8]) -> Result<Node<'_>, DecodeError> {
    let text =
        std::str::from_utf8(data).map_err(|error| invalid(error.valid_up_to(), "invalid UTF-8"))?;
    let mut p = Parser { text, pos: 0 };
    let node = p.value(0)?;
    p.space();
    if p.pos != text.len() {
        return Err(p.fail("trailing characters"));
    }
    Ok(node)
}

impl<'a> Parser<'a> {
    fn fail(&self, what: &str) -> DecodeError {
        invalid(self.pos, what)
    }

    fn peek(&self) -> Option<u8> {
        self.text.as_bytes().get(self.pos).copied()
    }

    /// The input from start to the current position.
    fn since(&self, start: usize) -> &'a str {
        self.text.get(start..self.pos).unwrap_or_default()
    }

    fn space(&mut self) {
        while matches!(self.peek(), Some(b' ' | b'\t' | b'\n' | b'\r')) {
            self.pos += 1;
        }
    }

    /// Consumes c if it comes next.
    fn accept(&mut self, c: u8) -> bool {
        if self.peek() == Some(c) {
            self.pos += 1;
            return true;
        }
        false
    }

    /// Parses one value inside depth arrays and objects.
    fn value(&mut self, depth: usize) -> Result<Node<'a>, DecodeError> {
        self.space();
        let start = self.pos;
        let Some(c) = self.peek() else {
            return Err(self.fail("an unexpected end of input"));
        };
        let kind = match c {
            b'{' | b'[' => {
                if depth + 1 >= MAX_DEPTH {
                    return Err(DecodeError::new(
                        DecodeError::TOO_DEEP,
                        Some(format!(
                            "at most {} nested arrays and objects",
                            MAX_DEPTH - 1
                        )),
                        Some(format!("more at offset {}", self.pos)),
                    ));
                }
                if c == b'{' {
                    self.object(depth + 1)?
                } else {
                    self.array(depth + 1)?
                }
            }
            b'"' => Kind::String(self.string()?),
            b't' => self.literal("true", Kind::True)?,
            b'f' => self.literal("false", Kind::False)?,
            b'n' => self.literal("null", Kind::Null)?,
            _ => self.number()?,
        };
        Ok(Node {
            raw: self.since(start),
            at: start,
            kind,
        })
    }

    /// Reads true, false or null, failing at the first byte that differs, like serde_json.
    fn literal(&mut self, word: &str, kind: Kind<'a>) -> Result<Kind<'a>, DecodeError> {
        for &b in word.as_bytes() {
            if self.peek() != Some(b) {
                return Err(self.fail("an invalid literal"));
            }
            self.pos += 1;
        }
        Ok(kind)
    }

    fn object(&mut self, depth: usize) -> Result<Kind<'a>, DecodeError> {
        let mut members = Members::default();
        self.pos += 1;
        self.space();
        if self.accept(b'}') {
            return Ok(Kind::Object(members));
        }
        loop {
            self.space();
            if self.peek() != Some(b'"') {
                return Err(self.fail("a missing key"));
            }
            let key_at = self.pos;
            let key = self.string()?;
            if members.find(&key).is_some() {
                let found = format!("{} at offset {key_at}", quote(&key));
                return Err(
                    DecodeError::new(DecodeError::DUPLICATE_KEY, None, Some(found)).at(&key),
                );
            }
            self.space();
            if !self.accept(b':') {
                return Err(self.fail("a missing colon"));
            }
            let value = self.value(depth).map_err(|error| error.at(&key))?;
            members.push(key, value);
            self.space();
            if self.accept(b'}') {
                return Ok(Kind::Object(members));
            }
            if !self.accept(b',') {
                return Err(self.fail("a missing comma or closing brace"));
            }
        }
    }

    fn array(&mut self, depth: usize) -> Result<Kind<'a>, DecodeError> {
        let mut items = Vec::new();
        self.pos += 1;
        self.space();
        if self.accept(b']') {
            return Ok(Kind::Array(items));
        }
        loop {
            let item = self
                .value(depth)
                .map_err(|error| error.at(&items.len().to_string()))?;
            items.push(item);
            self.space();
            if self.accept(b']') {
                return Ok(Kind::Array(items));
            }
            if !self.accept(b',') {
                return Err(self.fail("a missing comma or closing bracket"));
            }
        }
    }

    /// Parses a string, rejecting control characters and lone surrogates.
    fn string(&mut self) -> Result<Cow<'a, str>, DecodeError> {
        self.pos += 1;
        let mut chunk = self.pos;
        let mut text: Option<String> = None;
        loop {
            let Some(c) = self.peek() else {
                return Err(self.fail("an unterminated string"));
            };
            match c {
                b'"' => {
                    let tail = self.since(chunk);
                    self.pos += 1;
                    return Ok(match text {
                        None => Cow::Borrowed(tail),
                        Some(mut text) => {
                            text.push_str(tail);
                            Cow::Owned(text)
                        }
                    });
                }
                b'\\' => {
                    let tail = self.since(chunk);
                    let c = self.escape()?;
                    let text = text.get_or_insert_with(String::new);
                    text.push_str(tail);
                    text.push(c);
                    chunk = self.pos;
                }
                0..=0x1f => return Err(self.fail("a control character in a string")),
                _ => self.pos += 1,
            }
        }
    }

    /// Reads one escape sequence at the backslash. A \u escape of a high surrogate must be
    /// followed by one of a low surrogate, and a low surrogate can't stand alone. A bad escape
    /// or hex digit fails at that byte, and a surrogate that isn't half of a pair fails at the
    /// backslash.
    fn escape(&mut self) -> Result<char, DecodeError> {
        let start = self.pos;
        self.pos += 1;
        let c = match self.peek() {
            Some(b'"') => '"',
            Some(b'\\') => '\\',
            Some(b'/') => '/',
            Some(b'b') => '\u{8}',
            Some(b'f') => '\u{c}',
            Some(b'n') => '\n',
            Some(b'r') => '\r',
            Some(b't') => '\t',
            Some(b'u') => {
                self.pos += 1;
                return self.unicode(start);
            }
            _ => return Err(self.fail("an invalid escape")),
        };
        self.pos += 1;
        Ok(c)
    }

    /// Reads the hex digits of a \u escape that starts at start, and of its low surrogate.
    fn unicode(&mut self, start: usize) -> Result<char, DecodeError> {
        let lone = || invalid(start, "a lone surrogate");
        let unit = self.hex4()?;
        if (0xDC00..=0xDFFF).contains(&unit) {
            return Err(lone());
        }
        if !(0xD800..=0xDBFF).contains(&unit) {
            return char::from_u32(unit).ok_or_else(lone);
        }
        if self.peek() != Some(b'\\') || self.text.as_bytes().get(self.pos + 1) != Some(&b'u') {
            return Err(lone());
        }
        self.pos += 2;
        let low = self.hex4()?;
        if !(0xDC00..=0xDFFF).contains(&low) {
            return Err(lone());
        }
        char::from_u32(0x10000 + ((unit - 0xD800) << 10) + (low - 0xDC00)).ok_or_else(lone)
    }

    /// Reads the four hex digits of a \u escape, failing at the first that isn't one.
    fn hex4(&mut self) -> Result<u32, DecodeError> {
        let mut unit = 0;
        for _ in 0..4 {
            let Some(digit) = self.peek().and_then(|c| char::from(c).to_digit(16)) else {
                return Err(self.fail("an invalid escape"));
            };
            unit = unit * 16 + digit;
            self.pos += 1;
        }
        Ok(unit)
    }

    /// Consumes digits and returns how many.
    fn digits(&mut self) -> usize {
        let start = self.pos;
        while matches!(self.peek(), Some(b'0'..=b'9')) {
            self.pos += 1;
        }
        self.pos - start
    }

    /// Parses a number in JSON's grammar that is finite as an f64, like serde_json.
    fn number(&mut self) -> Result<Kind<'a>, DecodeError> {
        let start = self.pos;
        self.accept(b'-');
        if self.accept(b'0') {
            if matches!(self.peek(), Some(b'0'..=b'9')) {
                return Err(self.fail("a leading zero"));
            }
        } else if self.digits() == 0 {
            return Err(self.fail("an invalid value"));
        }
        if self.accept(b'.') && self.digits() == 0 {
            return Err(self.fail("an invalid number"));
        }
        if self.accept(b'e') || self.accept(b'E') {
            if !self.accept(b'+') {
                self.accept(b'-');
            }
            if self.digits() == 0 {
                return Err(self.fail("an invalid number"));
            }
        }
        if !self.since(start).parse::<f64>().is_ok_and(f64::is_finite) {
            return Err(invalid(start, "a number out of range"));
        }
        Ok(Kind::Number)
    }
}

/// A type strictgen generates, which decodes itself from JSON strictly: unknown keys, missing
/// required keys, explicit nulls for optional keys, a key given twice and values of the wrong
/// type fail with a [DecodeError], the same one Go and TypeScript report. Once the whole
/// value has decoded, its constraints, like a maximum length, are checked in the order Go and
/// TypeScript check them.
pub trait Decode: Sized {
    /// Decodes JSON text, given as a str or as bytes, then checks its constraints.
    ///
    /// # Errors
    ///
    /// A [DecodeError] when the text isn't JSON, doesn't fit the type or breaks a constraint.
    fn from_json(json: impl AsRef<[u8]>) -> Result<Self, DecodeError> {
        let value = Self::decode_node(&parse(json.as_ref())?)?;
        value.check()?;
        Ok(value)
    }

    /// Decodes a parsed value, without checking its constraints.
    ///
    /// # Errors
    ///
    /// A [DecodeError] when the value doesn't fit the type.
    #[doc(hidden)]
    fn decode_node(node: &Node<'_>) -> Result<Self, DecodeError>;

    /// Checks the constraints of a decoded value: its own, then those of the values inside it.
    ///
    /// # Errors
    ///
    /// A [DecodeError] for the first constraint the value breaks.
    #[doc(hidden)]
    fn check(&self) -> Result<(), DecodeError> {
        Ok(())
    }
}

/// A JSON string.
pub(super) fn string<'n>(node: &'n Node<'_>) -> Result<&'n str, DecodeError> {
    match &node.kind {
        Kind::String(text) => Ok(text),
        _ => Err(mismatch("a string", node)),
    }
}

/// A JSON integer that fits an i64. A fraction like 1.5, a spelling like 1.0 or 1e2, and -0,
/// which serde_json reads as a float, fail with wrong_type. An integer past the i64 range fails
/// with out_of_range_integer.
fn integer(node: &Node<'_>) -> Result<i64, DecodeError> {
    if !matches!(node.kind, Kind::Number) {
        return Err(mismatch("an integer", node));
    }
    let raw = node.raw;
    if raw.contains(['.', 'e', 'E']) || raw == "-0" {
        return Err(DecodeError::new(
            DecodeError::WRONG_TYPE,
            Some("an integer".to_owned()),
            Some(raw.to_owned()),
        ));
    }
    raw.parse().map_err(|_| {
        DecodeError::new(
            DecodeError::OUT_OF_RANGE_INTEGER,
            Some("an integer from -9223372036854775808 to 9223372036854775807".to_owned()),
            Some(raw.to_owned()),
        )
    })
}

/// A JSON boolean.
fn boolean(node: &Node<'_>) -> Result<bool, DecodeError> {
    match node.kind {
        Kind::True => Ok(true),
        Kind::False => Ok(false),
        _ => Err(mismatch("a boolean", node)),
    }
}

/// Any JSON value, null included.
fn json_value(node: &Node<'_>) -> Result<serde_json::Value, DecodeError> {
    Ok(match &node.kind {
        Kind::Null => serde_json::Value::Null,
        Kind::True => serde_json::Value::Bool(true),
        Kind::False => serde_json::Value::Bool(false),
        Kind::Number => serde_json::Value::Number(number(node)?),
        Kind::String(text) => serde_json::Value::String(text.clone().into_owned()),
        Kind::Array(items) => {
            serde_json::Value::Array(items.iter().map(json_value).collect::<Result<_, _>>()?)
        }
        Kind::Object(members) => serde_json::Value::Object(
            members
                .entries
                .iter()
                .map(|(name, item)| Ok((name.clone().into_owned(), json_value(item)?)))
                .collect::<Result<_, DecodeError>>()?,
        ),
    })
}

/// A finite JSON number. An integer that fits a u64 or an i64 stays one, as serde_json reads it.
/// Any other number, -0 included, is the nearest f64, read by Rust's own parser, which rounds
/// correctly where serde_json's default parser can be a step off, so constraints compare the
/// same value as in Go and TypeScript.
fn number(node: &Node<'_>) -> Result<serde_json::Number, DecodeError> {
    if !matches!(node.kind, Kind::Number) {
        return Err(mismatch("a number", node));
    }
    let raw = node.raw;
    if let Ok(value) = raw.parse::<u64>() {
        return Ok(value.into());
    }
    // -0 parses as the i64 0, which would lose its sign.
    if let Some(value) = raw.parse::<i64>().ok().filter(|&value| value != 0) {
        return Ok(value.into());
    }
    raw.parse::<f64>()
        .ok()
        .and_then(serde_json::Number::from_f64)
        .ok_or_else(|| invalid(node.at, "a number out of range"))
}

impl Decode for String {
    fn decode_node(node: &Node<'_>) -> Result<Self, DecodeError> {
        string(node).map(str::to_owned)
    }
}

impl Decode for i64 {
    fn decode_node(node: &Node<'_>) -> Result<Self, DecodeError> {
        integer(node)
    }
}

impl Decode for bool {
    fn decode_node(node: &Node<'_>) -> Result<Self, DecodeError> {
        boolean(node)
    }
}

/// Keeps a finite JSON number. serde_json writes it as it reads it, so 12 re-encodes as 12 and
/// 1E2 as 100.0.
impl Decode for serde_json::Number {
    fn decode_node(node: &Node<'_>) -> Result<Self, DecodeError> {
        number(node)
    }
}

/// Keeps any JSON value, null included.
impl Decode for serde_json::Value {
    fn decode_node(node: &Node<'_>) -> Result<Self, DecodeError> {
        json_value(node)
    }
}

impl<T: Decode> Decode for Box<T> {
    fn decode_node(node: &Node<'_>) -> Result<Self, DecodeError> {
        T::decode_node(node).map(Box::new)
    }

    fn check(&self) -> Result<(), DecodeError> {
        T::check(self)
    }
}

impl<T: Decode> Decode for Vec<T> {
    fn decode_node(node: &Node<'_>) -> Result<Self, DecodeError> {
        let Kind::Array(items) = &node.kind else {
            return Err(mismatch("an array", node));
        };
        items
            .iter()
            .enumerate()
            .map(|(i, item)| T::decode_node(item).map_err(|error| error.at(&i.to_string())))
            .collect()
    }
}

/// Decodes a JSON object whose keys decode as K, like an enum or an id, and values as V.
impl<K: Decode + Ord, V: Decode> Decode for BTreeMap<K, V> {
    fn decode_node(node: &Node<'_>) -> Result<Self, DecodeError> {
        if in_llm() {
            match &node.kind {
                Kind::Array(items) if LLM_ENTRIES => return llm_entries(node, items),
                Kind::Object(_) if LLM_OBJECTS => {}
                _ => return Err(mismatch(LLM_MAP_EXPECTED, node)),
            }
        }
        let Kind::Object(members) = &node.kind else {
            return Err(mismatch("an object", node));
        };
        members
            .entries
            .iter()
            .map(|(name, item)| entry(name, item))
            .collect()
    }
}

/// Decodes one member of a map, its key as a JSON string. A key that fails fails at its own
/// path, like the value under it.
fn entry<K: Decode, V: Decode>(name: &str, node: &Node<'_>) -> Result<(K, V), DecodeError> {
    let key = K::decode_node(&Node::key(name)).map_err(|error| error.at(name))?;
    let value = V::decode_node(node).map_err(|error| error.at(name))?;
    Ok((key, value))
}

/// Any JSON value except `null` at the top, like `jsonValue`. Nested values may be anything.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
#[serde(transparent)]
pub struct NonNullJson(pub serde_json::Value);

impl Decode for NonNullJson {
    fn decode_node(node: &Node<'_>) -> Result<Self, DecodeError> {
        if matches!(node.kind, Kind::Null) {
            return Err(DecodeError::new(
                DecodeError::NULL_NOT_ALLOWED,
                Some("a JSON value other than null".to_owned()),
                None,
            ));
        }
        json_value(node).map(Self)
    }
}

/// Reads the keys of a JSON object into a struct and tracks the keys it read.
pub(super) struct Object<'n, 'a> {
    members: &'n Members<'a>,
    used: Vec<bool>,
}

impl<'n, 'a> Object<'n, 'a> {
    /// Starts decoding a JSON object strictly: read its keys in schema order, then finish, which
    /// fails on the first key, in input order, that wasn't read.
    pub(super) fn new(node: &'n Node<'a>) -> Result<Self, DecodeError> {
        let Kind::Object(members) = &node.kind else {
            return Err(mismatch("an object", node));
        };
        Ok(Self {
            members,
            used: vec![false; members.entries.len()],
        })
    }

    /// Reads a key that must be present. A missing key fails at its own path.
    pub(super) fn required<T: Decode>(&mut self, key: &str) -> Result<T, DecodeError> {
        self.read(key, false)?
            .ok_or_else(|| DecodeError::new(DecodeError::MISSING_KEY, None, None).at(key))
    }

    /// Reads an optional key, None when it is absent. An explicit null fails, unless the type
    /// takes any JSON value, or an LLM decode runs, where null stands for absent.
    pub(super) fn optional<T: Decode>(&mut self, key: &str) -> Result<Option<T>, DecodeError> {
        self.read(key, true)
    }

    /// Reads a key, None when it is absent, or when it is optional and null in an LLM decode.
    fn read<T: Decode>(&mut self, key: &str, optional: bool) -> Result<Option<T>, DecodeError> {
        let Some(i) = self.members.find(key) else {
            return Ok(None);
        };
        let Some((_, node)) = self.members.entries.get(i) else {
            return Ok(None);
        };
        if let Some(used) = self.used.get_mut(i) {
            *used = true;
        }
        if optional && matches!(node.kind, Kind::Null) && in_llm() {
            return Ok(None);
        }
        T::decode_node(node)
            .map(Some)
            .map_err(|error| error.at(key))
    }

    /// Fails on the first key, in input order, that wasn't read, at its own path.
    pub(super) fn finish(self) -> Result<(), DecodeError> {
        for ((name, _), used) in self.members.entries.iter().zip(&self.used) {
            if !used {
                return Err(DecodeError::new(DecodeError::UNKNOWN_KEY, None, None).at(name));
            }
        }
        Ok(())
    }
}

/// Lists the values an enum or a tagged union takes, quoted, in the schema's order.
fn one_of(values: &[&str]) -> String {
    let quoted: Vec<String> = values.iter().map(|v| quote(v)).collect();
    format!("one of {}", quoted.join(", "))
}

/// The error for a string an enum doesn't list: not_in_enum, naming the values in the schema's
/// order, or not_const for an enum of one value.
pub(super) fn not_in_enum(text: &str, values: &[&str]) -> DecodeError {
    if let [only] = values {
        return DecodeError::new(DecodeError::NOT_CONST, Some(quote(only)), Some(quote(text)));
    }
    DecodeError::new(
        DecodeError::NOT_IN_ENUM,
        Some(one_of(values)),
        Some(quote(text)),
    )
}

/// Reads the tag key of a tagged union. A missing tag fails with missing_key and a tag that
/// isn't a string with wrong_type, at the tag's path.
pub(super) fn tag<'n>(node: &'n Node<'_>, key: &str) -> Result<&'n str, DecodeError> {
    let Kind::Object(members) = &node.kind else {
        return Err(mismatch("an object", node));
    };
    let Some((_, tag)) = members.find(key).and_then(|i| members.entries.get(i)) else {
        return Err(DecodeError::new(DecodeError::MISSING_KEY, None, None).at(key));
    };
    string(tag).map_err(|error| error.at(key))
}

/// The error for a tag no branch has, naming the tags in the schema's order, at the tag's path.
pub(super) fn bad_tag(key: &str, text: &str, tags: &[&str]) -> DecodeError {
    DecodeError::new(DecodeError::BAD_TAG, Some(one_of(tags)), Some(quote(text))).at(key)
}

/// Runs one variant of an untagged union. When it fails, the entries of maps it read are
/// dropped, so only the variant used notes its own.
pub(super) fn attempt<T>(
    decode: impl FnOnce() -> Result<T, DecodeError>,
) -> Result<T, DecodeError> {
    let entries = LLM.with(|cell| {
        cell.borrow()
            .as_ref()
            .map_or(0, |state| state.entries.len())
    });
    let result = decode();
    if result.is_err() {
        LLM.with(|cell| {
            if let Some(state) = cell.borrow_mut().as_mut() {
                state.entries.truncate(entries);
            }
        });
    }
    result
}

/// Moves the error of a check under an object key, so it has the key's path.
pub(super) fn within(key: &str, result: Result<(), DecodeError>) -> Result<(), DecodeError> {
    result.map_err(|error| error.at(key))
}

/// Shows n things, like "1 character" or "3 items".
fn count(n: usize, one: &str, many: &str) -> String {
    if n == 1 {
        format!("1 {one}")
    } else {
        format!("{n} {many}")
    }
}

/// Checks a count of things against a minimum and a maximum.
fn check_count(
    n: usize,
    min: Option<usize>,
    max: Option<usize>,
    one: &str,
    many: &str,
) -> Result<(), DecodeError> {
    if let Some(min) = min.filter(|&min| n < min) {
        return Err(DecodeError::new(
            DecodeError::TOO_SHORT,
            Some(format!("at least {}", count(min, one, many))),
            Some(count(n, one, many)),
        ));
    }
    if let Some(max) = max.filter(|&max| n > max) {
        return Err(DecodeError::new(
            DecodeError::TOO_LONG,
            Some(format!("at most {}", count(max, one, many))),
            Some(count(n, one, many)),
        ));
    }
    Ok(())
}

/// Checks the length of a string in code points, like Go and TypeScript count it.
pub(super) fn check_length(
    text: &str,
    min: Option<usize>,
    max: Option<usize>,
) -> Result<(), DecodeError> {
    check_count(text.chars().count(), min, max, "character", "characters")
}

/// Checks the number of items of an array, then that no two are equal, then each item with
/// item. Two items are equal when their RFC 8785 canonical JSON is, as in Go and TypeScript, so
/// 1 and 1.0 are equal and key order doesn't count. The error is at the later of the two.
pub(super) fn check_unique_items<T: Serialize>(
    items: &[T],
    min: Option<usize>,
    max: Option<usize>,
    item: impl Fn(&T) -> Result<(), DecodeError>,
) -> Result<(), DecodeError> {
    check_count(items.len(), min, max, "item", "items")?;
    let mut seen = HashMap::with_capacity(items.len());
    for (i, value) in items.iter().enumerate() {
        let json = serde_json::to_value(value).map_err(|error| {
            DecodeError::new(
                DecodeError::WRONG_TYPE,
                Some("a JSON value".to_owned()),
                Some(error.to_string()),
            )
            .at(&i.to_string())
        })?;
        let mut key = String::new();
        canonical(&json, &mut key);
        if let Some(first) = seen.get(&key) {
            return Err(DecodeError::new(
                DecodeError::NOT_UNIQUE,
                Some("unique items".to_owned()),
                Some(format!("a repeat of item {first}")),
            )
            .at(&i.to_string()));
        }
        seen.insert(key, i);
    }
    for (i, value) in items.iter().enumerate() {
        item(value).map_err(|error| error.at(&i.to_string()))?;
    }
    Ok(())
}

/// Writes a value's RFC 8785 canonical JSON: object keys sorted by UTF-16 code units, numbers as
/// JavaScript writes them with -0 as 0, and strings escaped as JSON.stringify does.
fn canonical(value: &serde_json::Value, out: &mut String) {
    match value {
        serde_json::Value::Null => out.push_str("null"),
        serde_json::Value::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
        // Adding 0.0 turns -0 into 0 and leaves every other number as it is.
        serde_json::Value::Number(n) => match n.as_f64() {
            Some(number) => out.push_str(&number_text(number + 0.0)),
            None => out.push_str(&n.to_string()),
        },
        serde_json::Value::String(text) => canonical_string(text, out),
        serde_json::Value::Array(items) => {
            out.push('[');
            for (i, item) in items.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                canonical(item, out);
            }
            out.push(']');
        }
        serde_json::Value::Object(map) => {
            let mut keys: Vec<&String> = map.keys().collect();
            keys.sort_by(|a, b| a.encode_utf16().cmp(b.encode_utf16()));
            out.push('{');
            for (i, key) in keys.into_iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                canonical_string(key, out);
                out.push(':');
                canonical(&map[key], out);
            }
            out.push('}');
        }
    }
}

/// Writes a string as JSON.stringify does: " and \ escaped, \b, \f, \n, \r and \t, and the other
/// control characters as \u and four lower case hex digits.
fn canonical_string(text: &str, out: &mut String) {
    out.push('"');
    for c in text.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\u{8}' => out.push_str("\\b"),
            '\u{c}' => out.push_str("\\f"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\u{0}'..='\u{1f}' => {
                let code = u32::from(c);
                out.push_str("\\u00");
                for shift in [4, 0] {
                    out.push(char::from_digit((code >> shift) & 0xf, 16).unwrap_or('0'));
                }
            }
            _ => out.push(c),
        }
    }
    out.push('"');
}

/// Checks that a string matches the pattern at index in PATTERNS. As JSON Schema says, a pattern
/// matches anywhere in the string unless it anchors itself with ^ or $. The patterns compile
/// once, on first use. strictgen only writes patterns that compile well within the size limit,
/// which is set here so a later regex release can't lower it.
pub(super) fn check_pattern(text: &str, index: usize) -> Result<(), DecodeError> {
    static COMPILED: std::sync::LazyLock<Vec<regex::Regex>> = std::sync::LazyLock::new(|| {
        PATTERNS
            .iter()
            .map(|(regex, _)| {
                regex::RegexBuilder::new(regex)
                    .size_limit(10 << 20)
                    .build()
                    .expect("strictgen writes every pattern in a form regex compiles")
            })
            .collect()
    });
    if COMPILED[index].is_match(text) {
        return Ok(());
    }
    Err(DecodeError::new(
        DecodeError::PATTERN_MISMATCH,
        Some(format!("matching {}", PATTERNS[index].1)),
        Some(quote(text)),
    ))
}

/// The error for a string that isn't in its format.
fn bad_format(expected: &str, text: &str) -> DecodeError {
    DecodeError::new(
        DecodeError::BAD_FORMAT,
        Some(expected.to_owned()),
        Some(quote(text)),
    )
}

/// The number count ASCII digits from start of bytes stand for, or None when they aren't all digits.
fn digits(bytes: &[u8], start: usize, count: usize) -> Option<u32> {
    bytes
        .get(start..start + count)?
        .iter()
        .try_fold(0, |n, &b| {
            b.is_ascii_digit().then(|| n * 10 + u32::from(b - b'0'))
        })
}

/// True when bytes start with a full-date: YYYY-MM-DD, a day the month has, Gregorian leap years.
fn date_at(bytes: &[u8]) -> bool {
    let (Some(year), Some(month), Some(day)) = (
        digits(bytes, 0, 4),
        digits(bytes, 5, 2),
        digits(bytes, 8, 2),
    ) else {
        return false;
    };
    if bytes[4] != b'-' || bytes[7] != b'-' || !(1..=12).contains(&month) || day < 1 {
        return false;
    }
    let leap = year % 4 == 0 && (year % 100 != 0 || year % 400 == 0);
    let days = match month {
        2 if leap => 29,
        2 => 28,
        4 | 6 | 9 | 11 => 30,
        _ => 31,
    };
    day <= days
}

/// Checks that a string is a date: an RFC 3339 full-date, like 2024-02-29.
pub(super) fn check_date(text: &str) -> Result<(), DecodeError> {
    if text.len() == 10 && date_at(text.as_bytes()) {
        Ok(())
    } else {
        Err(bad_format("a date", text))
    }
}

/// Checks that a string is a date-time: an RFC 3339 date-time, like 2024-02-29T23:59:60.5-01:30.
/// T and Z may be lower case, a fraction has one digit or more, and a leap second is 23:59:60
/// in UTC.
pub(super) fn check_date_time(text: &str) -> Result<(), DecodeError> {
    if is_date_time(text.as_bytes()) {
        Ok(())
    } else {
        Err(bad_format("a date-time", text))
    }
}

fn is_date_time(b: &[u8]) -> bool {
    if b.len() < 20
        || !date_at(b)
        || !matches!(b[10], b'T' | b't')
        || b[13] != b':'
        || b[16] != b':'
    {
        return false;
    }
    let (Some(hour), Some(minute), Some(second)) =
        (digits(b, 11, 2), digits(b, 14, 2), digits(b, 17, 2))
    else {
        return false;
    };
    if hour > 23 || minute > 59 || second > 60 {
        return false;
    }
    let mut i = 19;
    if b[i] == b'.' {
        i += 1;
        let start = i;
        while b.get(i).is_some_and(u8::is_ascii_digit) {
            i += 1;
        }
        if i == start {
            return false;
        }
    }
    let offset: i64 = match b.get(i) {
        Some(b'Z' | b'z') => {
            i += 1;
            0
        }
        Some(&sign @ (b'+' | b'-')) => {
            let (Some(hours), Some(minutes)) = (digits(b, i + 1, 2), digits(b, i + 4, 2)) else {
                return false;
            };
            if b.get(i + 3) != Some(&b':') || hours > 23 || minutes > 59 {
                return false;
            }
            i += 6;
            let offset = i64::from(hours * 60 + minutes);
            match sign {
                b'-' => -offset,
                _ => offset,
            }
        }
        _ => return false,
    };
    if i != b.len() {
        return false;
    }
    second != 60 || (i64::from(hour * 60 + minute) - offset).rem_euclid(1440) == 1439
}

/// Checks that a string is a UUID: RFC 9562's text form, 8-4-4-4-12 hex digits in either case,
/// of any version.
pub(super) fn check_uuid(text: &str) -> Result<(), DecodeError> {
    let bytes = text.as_bytes();
    let valid = bytes.len() == 36
        && bytes.iter().enumerate().all(|(i, &b)| {
            if matches!(i, 8 | 13 | 18 | 23) {
                b == b'-'
            } else {
                b.is_ascii_hexdigit()
            }
        });
    if valid {
        Ok(())
    } else {
        Err(bad_format("a UUID", text))
    }
}

/// Checks the number of items of an array, then each item with item.
pub(super) fn check_items<T>(
    items: &[T],
    min: Option<usize>,
    max: Option<usize>,
    item: impl Fn(&T) -> Result<(), DecodeError>,
) -> Result<(), DecodeError> {
    check_count(items.len(), min, max, "item", "items")?;
    for (i, value) in items.iter().enumerate() {
        item(value).map_err(|error| error.at(&i.to_string()))?;
    }
    Ok(())
}

/// Checks the number of keys of a map, then, in key order, which is code point order, each key
/// with key and its value with value, at the key's path, which name gives.
pub(super) fn check_entries<K, V>(
    map: &BTreeMap<K, V>,
    min: Option<usize>,
    max: Option<usize>,
    name: impl Fn(&K) -> &str,
    key: impl Fn(&K) -> Result<(), DecodeError>,
    value: impl Fn(&V) -> Result<(), DecodeError>,
) -> Result<(), DecodeError> {
    check_count(map.len(), min, max, "key", "keys")?;
    for (k, v) in map {
        key(k).map_err(|error| {
            // An LLM decode gives the error of a key's own check the path of the entry's key.
            LLM.with(|cell| {
                if let Some(state) = cell.borrow_mut().as_mut() {
                    state.key = true;
                }
            });
            error.at(name(k))
        })?;
        value(v).map_err(|error| error.at(name(k)))?;
    }
    Ok(())
}

/// The error for a value outside a limit: op is >=, >, <= or <, or % for a multiple, and text
/// is the bound as errors show it.
fn limit_error(op: &str, text: &str, found: String) -> DecodeError {
    let (code, expected) = match op {
        ">=" | ">" => (DecodeError::TOO_SMALL, format!("{op} {text}")),
        "<=" | "<" => (DecodeError::TOO_LARGE, format!("{op} {text}")),
        _ => (
            DecodeError::NOT_MULTIPLE_OF,
            format!("a multiple of {text}"),
        ),
    };
    DecodeError::new(code, Some(expected), Some(found))
}

/// Checks an integer against each limit in order, given as (op, bound, text).
pub(super) fn check_integer(value: i64, limits: &[(&str, i64, &str)]) -> Result<(), DecodeError> {
    for &(op, bound, text) in limits {
        let outside = match op {
            ">=" => value < bound,
            ">" => value <= bound,
            "<=" => value > bound,
            "<" => value >= bound,
            _ => value % bound != 0,
        };
        if outside {
            return Err(limit_error(op, text, value.to_string()));
        }
    }
    Ok(())
}

/// Checks a number against each limit in order, given as (op, bound, text). It compares the f64
/// serde_json reads, the nearest f64 to the number as spelled, as Go and TypeScript do. Without
/// serde_json's float_roundtrip feature, a rare number with many digits reads one step off.
pub(super) fn check_number(
    value: &serde_json::Number,
    limits: &[(&str, f64, &str)],
) -> Result<(), DecodeError> {
    let Some(number) = value.as_f64() else {
        return Err(DecodeError::new(
            DecodeError::WRONG_TYPE,
            Some("a number".to_owned()),
            Some(value.to_string()),
        ));
    };
    for &(op, bound, text) in limits {
        let outside = match op {
            ">=" => number < bound,
            ">" => number <= bound,
            "<=" => number > bound,
            _ => number >= bound,
        };
        if outside {
            return Err(limit_error(op, text, number_text(number)));
        }
    }
    Ok(())
}

/// Writes an f64 as JavaScript does, as Go and TypeScript errors show it: the shortest digits
/// that read back as the same f64, without an exponent from 1e-6 up to 1e21, and -0 kept.
fn number_text(number: f64) -> String {
    let text = format!("{number:e}");
    let (sign, text) = text
        .strip_prefix('-')
        .map_or(("", text.as_str()), |rest| ("-", rest));
    let (mantissa, exponent) = text.split_once('e').unwrap_or((text, "0"));
    let digits = mantissa.replace('.', "");
    // The number is 0.digits times 10 to the n.
    let n = exponent.parse::<i64>().unwrap_or(0) + 1;
    let k = i64::try_from(digits.len()).unwrap_or(i64::MAX);
    let zeros = |count: i64| "0".repeat(usize::try_from(count).unwrap_or(0));
    if k <= n && n <= 21 {
        return format!("{sign}{digits}{}", zeros(n - k));
    }
    if 0 < n && n <= 21 {
        let (head, tail) = digits.split_at(usize::try_from(n).unwrap_or(0));
        return format!("{sign}{head}.{tail}");
    }
    if -6 < n && n <= 0 {
        return format!("{sign}0.{}{digits}", zeros(-n));
    }
    let (first, rest) = digits.split_at(1);
    let point = if rest.is_empty() {
        String::new()
    } else {
        format!(".{rest}")
    };
    let exponent = n - 1;
    let exponent_sign = if exponent < 0 { '-' } else { '+' };
    format!("{sign}{first}{point}e{exponent_sign}{}", exponent.abs())
}

/// The patterns schemas check: each in the portable form, which Go's RE2 and ECMAScript read
/// the same way, and as the schema writes it, for errors.
const PATTERNS: [(&str, &str); 2] = [
    ("^[A-Z]{2}-[0-9]{4}$", "^[A-Z]{2}-[0-9]{4}$"),
    ("^[^ @]+@[^ @]+$", "^[^@ ]+@[^@ ]+$"),
];

/// True for JSON white space: space, tab, line feed and carriage return.
fn is_json_space(b: u8) -> bool {
    matches!(b, b' ' | b'\t' | b'\n' | b'\r')
}

/// The range `[start, end)` of `bytes` without the JSON white space at both ends.
fn trim_json_space(bytes: &[u8], mut start: usize, mut end: usize) -> (usize, usize) {
    while start < end && is_json_space(bytes[start]) {
        start += 1;
    }
    while end > start && is_json_space(bytes[end - 1]) {
        end -= 1;
    }
    (start, end)
}

/// The range inside the code fence around `bytes[start..end]`, already trimmed, or `None` when
/// the text isn't fenced: the opening line is three backticks, an info string of letters, digits
/// and `_+.-` and then only spaces, tabs or a carriage return, and the closing line is three
/// backticks after only spaces and tabs.
fn fenced(bytes: &[u8], start: usize, end: usize) -> Option<(usize, usize)> {
    const FENCE: &[u8] = b"```";
    if !bytes[start..end].starts_with(FENCE) {
        return None;
    }
    let line = start + bytes[start..end].iter().position(|&b| b == b'\n')?;
    let mut info = line;
    while info > start + 3 && matches!(bytes[info - 1], b' ' | b'\t' | b'\r') {
        info -= 1;
    }
    let plain = |b: &u8| b.is_ascii_alphanumeric() || matches!(b, b'_' | b'+' | b'.' | b'-');
    if !bytes[start + 3..info].iter().all(plain) {
        return None;
    }
    if end - 3 <= line || &bytes[end - 3..end] != FENCE {
        return None;
    }
    let mut close = end - 3;
    while close > line + 1 && matches!(bytes[close - 1], b' ' | b'\t') {
        close -= 1;
    }
    if close != line + 1 && bytes[close - 1] != b'\n' {
        return None;
    }
    Some(trim_json_space(bytes, line + 1, close))
}

/// `text` without each comma outside a string that only JSON white space separates from `}` or
/// `]`.
fn drop_trailing_commas(text: &str) -> String {
    let bytes = text.as_bytes();
    let mut out = String::with_capacity(text.len());
    let mut from = 0;
    let mut in_string = false;
    let mut i = 0;
    while i < bytes.len() {
        let b = bytes[i];
        if in_string {
            if b == b'\\' {
                i += 1;
            } else if b == b'"' {
                in_string = false;
            }
        } else if b == b'"' {
            in_string = true;
        } else if b == b',' {
            let mut next = i + 1;
            while next < bytes.len() && is_json_space(bytes[next]) {
                next += 1;
            }
            if next < bytes.len() && matches!(bytes[next], b'}' | b']') {
                out.push_str(&text[from..i]);
                from = i + 1;
            }
        }
        i += 1;
    }
    out.push_str(&text[from..]);
    out
}

/// Fixes only the JSON syntax LLMs often get wrong, and nothing else: removes a byte order mark
/// at the start, JSON white space at both ends, a code fence around the whole text and each
/// trailing comma outside a string. It never renames a key, fills in a value or changes one. Go
/// and TypeScript run the same steps, which `docs/llm.md` spells out.
#[must_use]
pub fn clean_llm_json(text: &str) -> String {
    let bytes = text.as_bytes();
    let first = if bytes.starts_with(&[0xef, 0xbb, 0xbf]) {
        3
    } else {
        0
    };
    let (start, end) = trim_json_space(bytes, first, bytes.len());
    let (from, to) = fenced(bytes, start, end).unwrap_or((start, end));
    drop_trailing_commas(&text[from..to])
}

/// Whether LLM decodes read a map given as an array of {"key": ..., "value": ...} entries. The
/// configured profiles give maps as entries or objects, told apart by their JSON type.
const LLM_ENTRIES: bool = true;

/// Whether LLM decodes read a map given as a JSON object.
const LLM_OBJECTS: bool = true;

/// What a map expects in an LLM decode, for a value in neither shape.
const LLM_MAP_EXPECTED: &str = "an array or an object";

/// What an LLM decode running on a thread notes.
#[derive(Default)]
struct LlmState {
    /// The offsets of the arrays it read as the entries of a map, in decode order.
    entries: Vec<usize>,
    /// Set when the constraint error is of a map key's own check.
    key: bool,
}

thread_local! {
    /// While an LLM decode runs on this thread: what it notes. None outside one.
    static LLM: std::cell::RefCell<Option<LlmState>> = const { std::cell::RefCell::new(None) };
}

/// One LLM decode on this thread. Dropping it restores the state of the decode that was running
/// before, even when decoding panics, so nothing reads a stale one.
struct LlmDecoding {
    saved: Option<LlmState>,
}

impl LlmDecoding {
    /// Starts an LLM decode, keeping the state before.
    fn start() -> Self {
        Self {
            saved: LLM.with(|cell| cell.replace(Some(LlmState::default()))),
        }
    }

    /// Ends the decode, restores the state before, and returns what it noted.
    fn finish(self) -> LlmState {
        let state = LLM
            .with(|cell| cell.borrow_mut().take())
            .unwrap_or_default();
        drop(self);
        state
    }
}

impl Drop for LlmDecoding {
    fn drop(&mut self) {
        let saved = self.saved.take();
        // The thread's storage may be gone when the thread exits; then there is nothing to restore.
        let _ = LLM.try_with(|cell| cell.replace(saved));
    }
}

/// True while an LLM decode runs on this thread.
fn in_llm() -> bool {
    LLM.with(|cell| cell.borrow().is_some())
}

/// The value of the key name of an object node, if it is one and has the key.
fn member<'n, 'a>(node: &'n Node<'a>, name: &str) -> Option<&'n Node<'a>> {
    let Kind::Object(members) = &node.kind else {
        return None;
    };
    members
        .find(name)
        .and_then(|i| members.entries.get(i))
        .map(|(_, item)| item)
}

/// Decodes a map an LLM gave as an array of {"key": ..., "value": ...} entries, in order. Each
/// entry is an object with exactly those keys, read like a struct, the key at /i/key and the
/// value at /i/value. A key given twice fails with duplicate_key at the later entry's key. The
/// array's offset is noted, so a constraint error can be given the entry's path.
fn llm_entries<K: Decode + Ord, V: Decode>(
    node: &Node<'_>,
    items: &[Node<'_>],
) -> Result<BTreeMap<K, V>, DecodeError> {
    let mut out = BTreeMap::new();
    for (i, item) in items.iter().enumerate() {
        let index = i.to_string();
        let read = || -> Result<(K, V), DecodeError> {
            let mut object = Object::new(item)?;
            let key = object.required("key")?;
            let value = object.required("value")?;
            object.finish()?;
            Ok((key, value))
        };
        let (key, value) = read().map_err(|error| error.at(&index))?;
        if out.contains_key(&key) {
            let name = member(item, "key")
                .and_then(|key| string(key).ok())
                .unwrap_or_default();
            return Err(
                DecodeError::new(DecodeError::DUPLICATE_KEY, None, Some(quote(name)))
                    .at("key")
                    .at(&index),
            );
        }
        out.insert(key, value);
    }
    LLM.with(|cell| {
        if let Some(state) = cell.borrow_mut().as_mut() {
            state.entries.push(node.at);
        }
    });
    Ok(out)
}

/// Decodes the JSON text a model gave for a provider-ready schema as T, undoing the projection:
/// null for an optional key is absent, and maps are read in the shapes the profiles give. A type
/// that isn't an object is read from the "value" key of the object around it, when wrapped is
/// set. Then the constraints of the whole value are checked. Every error has the path of the
/// model's payload.
pub(super) fn from_llm<T: Decode>(text: &str, wrapped: bool) -> Result<T, DecodeError> {
    let root = parse(text.as_bytes())?;
    let decoding = LlmDecoding::start();
    let (value, node) = if wrapped {
        let mut object = Object::new(&root)?;
        let value: T = object.required("value")?;
        object.finish()?;
        (value, member(&root, "value"))
    } else {
        (T::decode_node(&root)?, Some(&root))
    };
    if let Err(error) = value.check() {
        let state = decoding.finish();
        let path = llm_path(node, &error.path, &state);
        let path = if wrapped {
            format!("/value{path}")
        } else {
            path
        };
        return Err(DecodeError { path, ..error });
    }
    drop(decoding);
    Ok(value)
}

/// The path, in the payload under node, of a constraint error whose path is in the decoded value:
/// under a map read from entries, a key becomes the index of its entry, then key for an error of
/// the key itself, else value.
fn llm_path(mut node: Option<&Node<'_>>, path: &str, state: &LlmState) -> String {
    let segments: Vec<String> = match path.strip_prefix('/') {
        Some(rest) => rest
            .split('/')
            .map(|s| s.replace("~1", "/").replace("~0", "~"))
            .collect(),
        None => Vec::new(),
    };
    let mut out = String::new();
    for (i, segment) in segments.iter().enumerate() {
        if let Some(Node {
            kind: Kind::Array(items),
            at,
            ..
        }) = node
        {
            let found = state.entries.contains(at).then(|| {
                items.iter().position(|item| {
                    member(item, "key").and_then(|key| string(key).ok()) == Some(segment.as_str())
                })
            });
            if let Some(Some(j)) = found {
                out.push_str(&pointer(&j.to_string()));
                if i + 1 == segments.len() && state.key {
                    out.push_str("/key");
                    return out;
                }
                out.push_str("/value");
                node = items.get(j).and_then(|item| member(item, "value"));
                continue;
            }
        }
        out.push_str(&pointer(segment));
        node = node.and_then(|n| match &n.kind {
            Kind::Object(_) => member(n, segment),
            Kind::Array(items) => segment.parse::<usize>().ok().and_then(|j| items.get(j)),
            _ => None,
        });
    }
    out
}
